create table if not exists public.products(id text primary key,name text not null,price numeric not null,available boolean not null default true,sort_order int not null default 0);create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_id text unique not null,package_id text,package_name text not null,price numeric not null,player_uid text not null,player_name text,payment_method text not null,status text not null default 'pending',created_at timestamptz not null default now());alter table public.products enable row level security;alter table public.orders enable row level security;create policy "public read products" on public.products for select using(true);create policy "auth manage products" on public.products for all to authenticated using(true) with check(true);create policy "public create orders" on public.orders for insert to anon,authenticated with check(true);create policy "auth read orders" on public.orders for select to authenticated using(true);create policy "auth update orders" on public.orders for update to authenticated using(true) with check(true);insert into public.products(id,name,price,sort_order) values('level-all','Level Up Pass — All Levels',650,1),('level-6','Level 6',75,2),('level-10','Level 10',130,3),('level-15','Level 15',130,4),('level-20','Level 20',130,5),('level-25','Level 25',130,6),('level-30','Level 30',170,7),('weekly-lite','Weekly Lite',100,8),('weekly','Weekly',230,9),('monthly','Monthly',1150,10),('weekly-monthly','Weekly + Monthly',1350,11),('weekly-monthly-lite','Weekly + Monthly + Weekly Lite',1450,12),('d50','50 Diamonds',70,13),('d115','115 Diamonds',120,14),('d240','240 Diamonds',250,15),('d610','610 Diamonds',550,16) on conflict(id) do update set name=excluded.name,price=excluded.price,sort_order=excluded.sort_order;